namespace sv_1f339f16224c499ab5d5539bca8a71f1.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Holds per-circuit theme state. Registered as Scoped so each
/// SignalR circuit (user) gets its own independent instance.
/// </summary>
public sealed class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd"; // Bootstrap primary blue

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyStateChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyStateChanged();
        }
    }

    public event Action? OnChange;

    private void NotifyStateChanged() => OnChange?.Invoke();
}

using sv_1f339f16224c499ab5d5539bca8a71f1.Services;

namespace sv_1f339f16224c499ab5d5539bca8a71f1.Components.Theme;

/// <summary>
/// Immutable snapshot cascaded to all descendants so they can
/// read the current theme without injecting ThemeService directly.
/// </summary>
public sealed record ThemeInfo(ThemeMode Theme, string AccentColor);

@* 
    Interactive wrapper that lives in the circuit.
    Subscribes to ThemeService.OnChange and re-cascades a new
    ThemeInfo snapshot, causing all consuming descendants to re-render.
    Also pushes the theme to the DOM via JS so CSS can respond.
*@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeSvc
@inject IJSRuntime JS

<CascadingValue Value="CurrentTheme" IsFixed="false">
    @ChildContent
</CascadingValue>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }

    private ThemeInfo CurrentTheme => new(ThemeSvc.Theme, ThemeSvc.AccentColor);

    protected override void OnInitialized()
    {
        ThemeSvc.OnChange += HandleThemeChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        await ApplyThemeToDom();
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(async () =>
        {
            StateHasChanged();
            await ApplyThemeToDom();
        });
    }

    private async Task ApplyThemeToDom()
    {
        try
        {
            var themeName = ThemeSvc.Theme switch
            {
                ThemeMode.Dark => "dark",
                ThemeMode.Light => "light",
                _ => "auto"
            };
            await JS.InvokeVoidAsync("applyTheme", themeName, ThemeSvc.AccentColor);
        }
        catch (JSDisconnectedException) { }
    }

    public void Dispose()
    {
        ThemeSvc.OnChange -= HandleThemeChanged;
    }
}

@* Small badge shown in the header to display the active theme & accent. *@

<span class="theme-indicator" style="color: @Info.AccentColor;" title="Accent: @Info.AccentColor">
    @switch (Info.Theme)
    {
        case ThemeMode.Light:
            <span>☀️ Light</span>
            break;
        case ThemeMode.Dark:
            <span>🌙 Dark</span>
            break;
        default:
            <span>💻 System</span>
            break;
    }
</span>

@code {
    [CascadingParameter] public ThemeInfo Info { get; set; } = default!;
}

@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeSvc

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 480px;">
    <h5>Theme</h5>
    <div class="btn-group mb-3" role="group">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            <button type="button"
                    class="btn @(ThemeSvc.Theme == mode ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => ThemeSvc.Theme = mode">
                @mode
            </button>
        }
    </div>

    <h5>Accent Color</h5>
    <div class="d-flex align-items-center gap-2 mb-3">
        <input type="color" class="form-control form-control-color"
               value="@ThemeSvc.AccentColor"
               @onchange="OnAccentChanged" />
        <span style="color: @ThemeSvc.AccentColor; font-weight: bold;">
            @ThemeSvc.AccentColor
        </span>
    </div>

    <p class="text-muted small mb-0">
        Changes apply immediately across all pages and components.
    </p>
</div>

@code {
    private void OnAccentChanged(ChangeEventArgs e)
    {
        ThemeSvc.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }
}

// Applies the theme to the DOM so CSS can respond via
// [data-bs-theme] and the --accent-color custom property.
window.applyTheme = function (theme, accentColor) {
    const html = document.documentElement;

    if (theme === "auto") {
        html.removeAttribute("data-bs-theme");
    } else {
        html.setAttribute("data-bs-theme", theme);
    }

    html.style.setProperty("--accent-color", accentColor);
};

